INSERT INTO prompt_versions (
    version_name, prompt_type, prompt_content, description, created_by, created_at
) VALUES (
    #{versionName}, #{promptType}, #{promptContent}, #{description}, #{createdBy}, NOW()
)

mapper.update:
UPDATE prompt_versions 
SET is_default = 0 
WHERE prompt_type = #{promptType}

mapper.insert:
INSERT INTO prompt_ab_test_exposures (
    test_id, version_id, session_id, exposed_at
) VALUES (
    #{testId}, #{versionId}, #{sessionId}, NOW()
)

INSERT INTO prompt_optimization_suggestions (
    prompt_id, suggestion_type, suggestion_content, improvement, created_at
) VALUES (
    #{promptId}, #{suggestionType}, #{suggestionContent}, #{improvement}, NOW()
)

mapper.select:
SELECT * FROM prompt_optimization_suggestions 
WHERE prompt_id = #{promptId} 
ORDER BY created_at DESC

